  if (!f) return "";
  const a = G.findPos(layout, sel.anchorKey) || f;
  const rect = G.normalizeRange(a, f);
  let css = "";
  if (a.r !== f.r || a.c !== f.c) css += rectRule(root, layout, rect, `box-shadow:${RANGE_FILL};`);
